"""Apply the bounded AtlasNote 1.2.1 post-integration compatibility fix idempotently."""
from pathlib import Path
import base64, json, lzma, subprocess

root = Path.cwd().resolve()
patch = lzma.decompress(base64.b64decode(""))

check = subprocess.run(["git", "apply", "--check", "-"], input=patch, cwd=root)
if check.returncode == 0:
    subprocess.run(["git", "apply", "--whitespace=nowarn", "-"], input=patch, cwd=root, check=True)
    state = "applied"
else:
    reverse = subprocess.run(["git", "apply", "--reverse", "--check", "-"], input=patch, cwd=root)
    if reverse.returncode != 0:
        raise SystemExit("Compatibility patch is neither cleanly applicable nor already applied.")
    state = "already applied"

paths = [
    "src/app/App.tsx",
    "src/components/PdfIntake.tsx",
    "src/components/SettingsDialog.tsx",
    "src/reader/Reader.tsx",
    "src/online/PdfEngine.tsx",
    "src/online/react-runtime.ts",
    "vite.config.mjs",
    "tools/audit-local.mjs",
    "package.json",
    "package-lock.json",
]
(root / ".atlasnote-integration/source-paths.json").write_text(json.dumps(paths))
print(f"AtlasNote 1.2.1 compatibility patch: {state}; resolved lockfile retained.")
